const SimpleNumericStatisticSpecSchema = z
  .object({
    kind: z.enum(['avg', 'sum', 'min', 'max', 'std', 'count']).openapi({ title: 'Kind' }),
    weight_key: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Weight Key' }),
    goal: z.union([GoalSpecSchema, z.null().nullable()]).exactOptional(),
  })
  .openapi({
    title: 'SimpleNumericStatisticSpec',
    required: ['kind'],
    description:
      "A scalar numeric reduction (``avg``/``sum``/``min``/``max``/``std``/``count``).\n\n``weight_key`` (``avg`` only) turns the mean into a weighted mean, ``sum(w * x) / sum(w)``, where\neach score's weight ``w`` is read from its ``metadata`` under that key. Scores whose weight is\nmissing, non-numeric or negative are left out of that statistic.",
  })
  .openapi('SimpleNumericStatisticSpec')

const PercentileStatisticSpecSchema = z
  .object({
    kind: z.literal('percentile').default('percentile').exactOptional().openapi({ title: 'Kind' }),
    percentile: z.union([z.number(), z.int()]).openapi({ title: 'Percentile' }),
    goal: z.union([GoalSpecSchema, z.null().nullable()]).exactOptional(),
  })
  .openapi({
    title: 'PercentileStatisticSpec',
    required: ['percentile'],
    description:
      'The ``p``-th percentile (``0 &lt;= p &lt;= 100``), computed with the type-7 algorithm.',
  })
  .openapi('PercentileStatisticSpec')

const ClassificationStatisticSpecSchema = z
  .object({
    kind: z.enum(['precision', 'recall', 'f1']).openapi({ title: 'Kind' }),
    positive_label: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Positive Label' }),
    average: z
      .union([z.enum(['macro', 'micro', 'weighted']), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Average' }),
    expected_key: z.string().default('expected').exactOptional().openapi({ title: 'Expected Key' }),
    labels: z
      .union([z.array(z.string()), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Labels' }),
    goal: z.union([GoalSpecSchema, z.null().nullable()]).exactOptional(),
  })
  .openapi({
    title: 'ClassificationStatisticSpec',
    required: ['kind'],
    description:
      'A classification metric (``precision``/``recall``/``f1``) over ``(expected, predicted)`` pairs.\n\nThe predicted label is the score ``value``; the expected label is read from the score ``metadata``\nunder ``expected_key`` (default ``"expected"``). Provide **exactly one** of ``positive_label`` (a\nbinary metric scored against that one class) or ``average`` (a multi-class averaging scheme).\n\n``labels`` pins the class universe so filtered views keep a stable, comparable denominator.',
  })
  .openapi('ClassificationStatisticSpec')

const DisplayFormatSchema = z
  .enum(['number', 'percent', 'integer'])
  .openapi({
    title: 'DisplayFormat',
    description:
      "How an evaluator's numeric values render: ``percent``, ``integer`` or ``number``.",
  })
  .openapi('DisplayFormat')

const DisplaySpecSchema = z
  .object({
    format: z.union([DisplayFormatSchema, z.null().nullable()]).exactOptional(),
    unit: z
      .union([z.string().min(1).max(20), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Unit' }),
    decimals: z
      .union([z.int().min(0).max(10), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Decimals' }),
    metric: z
      .union([z.string().min(1).max(100), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Metric' }),
  })
  .openapi({
    title: 'DisplaySpec',
    description:
      'How the UI renders an evaluator\'s numeric values (scores, score-scale statistics, goal thresholds).\n\nDisplay only: stored values and computed statistics never change. ``percent`` reads the value as a\nfraction (0.63 renders as 63%), ``integer`` rounds it, ``number`` renders ``decimals`` decimals.\n``unit`` is a free suffix ("s", "ms", "chars"), not allowed with ``percent`` (its ``%`` is the unit).\nAll fields unset = the default rendering.\n\n``metric`` (run evaluators only) names the run evaluator metric this format applies to. Without it, the\nspec formats the main value and is the default format of every metric.',
    required: [],
  })
  .openapi('DisplaySpec')

const MetricDirectionSpecSchema = z
