const LogicalExpressionSchema: z.ZodType<LogicalExpressionType> = z
  .lazy(() =>
    z
      .object({
        type: z.enum(['and', 'or']).openapi({ title: 'Type' }),
        expressions: z
          .array(
            z.union([
              z.array(z.string()).superRefine((items, ctx) => {
                const seen = new Map()
                for (const [i, val] of items.entries()) {
                  const key = JSON.stringify(val)
                  if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                  else seen.set(key, i)
                }
              }),
              LogicalExpressionSchema,
              ToolPropertiesSchema,
            ]),
          )
          .openapi({ title: 'Expressions' }),
      })
      .openapi({ title: 'LogicalExpression', required: ['type', 'expressions'] }),
  )
  .openapi('LogicalExpression')

