const SkillAssetContentSchema = (() => {
  const Schema = z
    .xor([
      z
        .object({ rawContent: z.string().openapi({ title: 'raw_content' }) })
        .openapi({ title: 'raw_content', required: ['rawContent'] }),
      z
        .object({ textContent: z.string().openapi({ title: 'text_content' }) })
        .openapi({ title: 'text_content', required: ['textContent'] }),
    ])
    .and(
      z
        .object({ isExecutable: z.boolean().exactOptional().openapi({ title: 'is_executable' }) })
        .openapi({ required: [] }),
    )
  return z.preprocess((val: z.input<typeof Schema>, ctx) => {
    ;((ctx) => {
      const o = ctx.value
      if (typeof o !== 'object' || o === null || Array.isArray(o)) return
      for (const k of Object.keys(o)) {
        if (!['isExecutable'].includes(k)) {
          ctx.issues.push({ code: 'custom', path: [k], input: o })
        }
      }
    })(ctx)
    return val
  }, Schema)
})()
  .openapi({ additionalProperties: false })
  .openapi({ title: 'SkillAssetContent' })
  .openapi('SkillAssetContent')

