const ConversationAppendRequestSchema: z.ZodType<ConversationAppendRequestType> = (() => {
  const Schema = AppendConversationRequestSchema.and(
    z.object({ stream: z.literal(false).default(false).exactOptional() }).openapi({ required: [] }),
  )
  return z.preprocess((val: z.input<typeof Schema>, ctx) => {
    ;((ctx) => {
      const o = ctx.value
      if (typeof o !== 'object' || o === null || Array.isArray(o)) return
      for (const k of Object.keys(o)) {
        if (
          ![
            'inputs',
            'stream',
            'store',
            'handoff_execution',
            'completion_args',
            'tool_confirmations',
          ].includes(k)
        ) {
          ctx.issues.push({ code: 'custom', path: [k], input: o })
        }
      }
    })(ctx)
    return val
  }, Schema)
})().openapi('ConversationAppendRequest')

