const OCRPageConfidenceScoresSchema = z
  .object({
    word_confidence_scores: z
      .array(OCRConfidenceScoreSchema)
      .exactOptional()
      .openapi({
        title: 'Word Confidence Scores',
        description: "Word-level confidence scores (populated only for 'word' granularity)",
      }),
    average_page_confidence_score: z
      .number()
      .min(0)
      .max(1)
      .openapi({
        title: 'Average Page Confidence Score',
        description: 'Average confidence score for the page',
      }),
    minimum_page_confidence_score: z
      .number()
      .min(0)
      .max(1)
      .openapi({
        title: 'Minimum Page Confidence Score',
        description: 'Minimum confidence score for the page',
      }),
  })
  .openapi({
    title: 'OCRPageConfidenceScores',
    required: ['average_page_confidence_score', 'minimum_page_confidence_score'],
    description:
      "Confidence scores for an OCR page at various granularities.\n\nNote on page-level stats:\n- For 'page' and 'block' granularity: average/minimum are computed from per-token\n  exp(logprob). Neither ``word_confidence_scores`` nor ``token_scores`` is populated.\n  Per-block scores are attached to response blocks separately for 'block' granularity.\n- For 'word' granularity: average/minimum are computed from per-word confidence, where\n  each word's confidence is exp(mean(token_logprobs)) — a geometric mean over the\n  word's subword tokens. ``word_confidence_scores`` is populated.\n- For 'token' granularity (internal): average/minimum are computed from\n  ``token_scores``; ``token_scores`` is populated.",
  })
  .openapi('OCRPageConfidenceScores')

