const AgentsCompletionRequestSchema: z.ZodType<AgentsCompletionRequestType> = z
  .strictObject({
    max_tokens: z
      .union([z.int().min(0), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Max Tokens',
        description:
          "The maximum number of tokens to generate in the completion. The token count of your prompt plus `max_tokens` cannot exceed the model's context length.",
      }),
    stream: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Stream',
        description:
          'Whether to stream back partial progress. If set, tokens will be sent as data-only server-side events as they become available, with the stream terminated by a data: [DONE] message. Otherwise, the server will hold the request open until the timeout or until completion, with the response containing the full result as JSON.',
      }),
    stop: z
      .union([z.string(), z.array(z.string()), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Stop',
        description:
          'Stop generation if this token is detected. Or if one of these tokens is detected when providing an array',
      }),
    random_seed: z
      .union([z.int().min(0).max(9223372036854776000), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Random Seed',
        description:
          'The seed to use for random sampling. If set, different calls will generate deterministic results.',
      }),
    metadata: z
      .union([z.looseObject({}), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Metadata' }),
    messages: z
      .array(
        z
          .xor([SystemMessageSchema, UserMessageSchema, AssistantMessageSchema, ToolMessageSchema])
          .openapi({
            discriminator: {
              propertyName: 'role',
              mapping: {
                assistant: '#/components/schemas/AssistantMessage',
                system: '#/components/schemas/SystemMessage',
                tool: '#/components/schemas/ToolMessage',
                user: '#/components/schemas/UserMessage',
              },
            },
          }),
      )
      .openapi({
        examples: [
          [
            {
              role: 'user',
              content: 'Who is the best French painter? Answer in one short sentence.',
            },
          ],
        ],
        title: 'Messages',
        description:
          'The prompt(s) to generate completions for, encoded as a list of dict with role and content.',
      }),
    response_format: ResponseFormatSchema.exactOptional(),
    tools: z
      .union([
        z.array(
          z
            .xor([
              ToolSchema,
              ImageGenerationToolSchema,
              DocumentLibraryToolSchema,
              CustomConnectorSchema,
            ])
            .openapi({
              discriminator: {
                propertyName: 'type',
                mapping: {
                  function: '#/components/schemas/Tool',
                  image_generation: '#/components/schemas/ImageGenerationTool',
                  document_library: '#/components/schemas/DocumentLibraryTool',
                  connector: '#/components/schemas/CustomConnector',
                },
              },
            }),
        ),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({ title: 'Tools' }),
    tool_choice: z
      .union([ToolChoiceEnumSchema, NamedToolChoiceSchema])
      .default('auto')
      .exactOptional()
      .openapi({ title: 'Tool Choice' }),
    presence_penalty: z
      .union([z.number().min(-2).max(2), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Presence Penalty',
        description:
          'The `presence_penalty` determines how much the model penalizes the repetition of words or phrases. A higher presence penalty encourages the model to use a wider variety of words and phrases, making the output more diverse and creative.',
      }),
    frequency_penalty: z
      .union([z.number().min(-2).max(2), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Frequency Penalty',
        description:
          'The `frequency_penalty` penalizes the repetition of words based on their frequency in the generated text. A higher frequency penalty discourages the model from repeating words that have already appeared frequently in the output, promoting diversity and reducing repetition.',
      }),
    min_tokens: z
      .union([z.int().min(0), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Min Tokens' }),
    repetition_penalty: z
      .union([z.number().gt(0).max(2), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Repetition Penalty' }),
    top_k: z
      .union([z.int().min(-1), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Top K' }),
    logprobs: z
      .union([z.boolean(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Logprobs' }),
    top_logprobs: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Top Logprobs' }),
    prompt_logprobs: z
      .union([z.boolean(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Prompt Logprobs' }),
    top_prompt_logprobs: z
      .union([z.int(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Top Prompt Logprobs' }),
    n: z
      .union([z.int().min(1), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'N',
        description:
          'Number of completions to return for each request, input tokens are only billed once.',
      }),
    prediction: PredictionSchema.exactOptional().openapi({
      description:
        'Deprecated: the API accepts this field but ignores it, and it will be removed in a future major version.',
      deprecated: true,
    }),
    parallel_tool_calls: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({ title: 'Parallel Tool Calls' }),
    reasoning_effort: z.union([ReasoningEffortSchema, z.null().nullable()]).exactOptional(),
    prompt_mode: z
      .union([MistralPromptModeSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description:
          'Allows toggling between the reasoning mode and no system prompt. When set to `reasoning` the system prompt for reasoning models will be used.',
      }),
    guardrails: z
      .union([z.array(GuardrailConfigSchema), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Guardrails' }),
    prompt_cache_key: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Prompt Cache Key' }),
    service_tier: z
      .union([RequestedServiceTierSchema, z.null().nullable()])
      .exactOptional()
      .openapi({
        description: 'Determines whether to serve the request using priority or standard capacity.',
      }),
    agent_id: z
      .string()
      .openapi({ description: 'The ID of the agent to use for this completion.' }),
  })
  .openapi({ title: 'AgentsCompletionRequest', required: ['messages', 'agent_id'] })
  .openapi('AgentsCompletionRequest')

