const RunOwnershipFilterSchema = z
  .object({
    combinator: FilterCombinatorSchema.default('or').exactOptional(),
    creator_ids: z.array(z.uuid()).default([]).exactOptional().openapi({ title: 'Creator Ids' }),
    project_ids: z.array(z.uuid()).default([]).exactOptional().openapi({ title: 'Project Ids' }),
    starred_by_me: z.boolean().default(false).exactOptional().openapi({ title: 'Starred By Me' }),
  })
  .openapi({
    title: 'RunOwnershipFilter',
    description:
      'OR-able group isolating the "runs I care about" default (created by me OR in my starred projects).\n\nKept separate from the plain generic filters so it can OR internally while still AND-ing with\neverything else. The UI drives it via two sugar chips: "Created by me" writes `creator_ids`, and\n"Starred projects" sets `starred_by_me`. Dropping a chip clears its term and the OR collapses to the\nremaining one; dropping both leaves the group empty (no ownership scoping).\n\n`starred_by_me` is resolved server-side against the caller\'s favorites, so the client never has to\npage through projects to collect starred ids — and a caller with zero starred projects correctly\nmatches no runs (rather than falling through to the whole workspace). `project_ids` remains for\nexplicit, caller-supplied project scoping.',
    required: [],
  })
  .openapi('RunOwnershipFilter')

