const WorkflowExecutionRequestSchema = z
  .object({
    execution_id: z
      .union([z.string().max(256), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Execution Id',
        description:
          'Allows you to specify a custom execution ID. If not provided, a random ID will be generated.',
      }),
    input: z
      .union([z.looseObject({}), z.looseObject({}), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Input',
        description:
          "The input to the workflow. This should be a dictionary or a BaseModel that matches the workflow's input schema.",
      }),
    wait_for_result: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Wait For Result',
        description: 'If true, wait for the workflow to complete and return the result directly.',
      }),
    timeout_seconds: z
      .union([z.number(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Timeout Seconds',
        description: 'Maximum time to wait for completion when wait_for_result is true.',
      }),
    custom_tracing_attributes: z
      .union([z.record(z.string(), z.string()), z.null().nullable()])
      .exactOptional()
      .openapi({ title: 'Custom Tracing Attributes' }),
    force_new_trace: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        title: 'Force New Trace',
        description:
          "If true, ignore the caller's trace context and start a new, independent trace for this execution instead of joining the caller's trace.",
      }),
    traceparent: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Traceparent',
        description:
          "W3C trace context to join this execution to the caller's trace. Ignored when force_new_trace is set.",
      }),
    extensions: z
      .union([z.looseObject({}), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Extensions',
        description:
          'Plugin-specific data to propagate into WorkflowContext.extensions at execution time.',
      }),
    call_context: z
      .union([
        z
          .record(
            z.string(),
            z.union([
              z.boolean(),
              z.int().min(-9007199254740991).max(9007199254740991),
              z.string().regex(/^[A-Za-z0-9._:@\/-]{1,256}$/),
            ]),
          )
          .refine((val) => Object.keys(val).length <= 16)
          .superRefine((o, ctx) => {
            const regex = new RegExp('^[a-z][a-z0-9_]{0,63}$')
            for (const k of Object.keys(o)) {
              if (!regex.test(k)) {
                ctx.addIssue({ code: 'custom', path: [k] })
              }
            }
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({
        title: 'Call Context',
        description:
          'Cleartext technical values (ids, flags) for the code this call runs, read with `get_call_context()`. Not covered by payload encryption: never put customer content here.',
      }),
    task_queue: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Task Queue',
        description: 'Deprecated. Use deployment_name instead.',
        deprecated: true,
      }),
    deployment_name: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        title: 'Deployment Name',
        description: 'Name of the deployment to route this execution to',
      }),
  })
  .openapi({ title: 'WorkflowExecutionRequest', required: [] })
  .openapi('WorkflowExecutionRequest')

