const ActionAvailableSchema = z
  .object({
    status: z
      .literal('available')
      .default('available')
      .exactOptional()
      .openapi({ title: 'Status' }),
  })
  .openapi({
    title: 'ActionAvailable',
    description: 'The viewer may perform the action on the resource.',
    required: [],
  })
  .openapi('ActionAvailable')

const RotateUnavailableReasonSchema = z
  .enum(['unsupported_scope', 'key_expired', 'not_allowed'])
  .openapi({
    title: 'RotateUnavailableReason',
    description:
      'Machine-readable reason why an API key cannot be rotated.\n\nThis is the single field shared across services to describe rotation eligibility. An absent\nreason (None) means the key can be rotated; any value means it cannot, and identifies why so\nconsumers (e.g. the dashboard rotate button) can show an appropriate message without hardcoding\nthe rules. Consumers should treat unknown values as "rotation unavailable".\n\nKey-state reasons depend on the key\'s own state (e.g. expiry) and are determined where the key\nlives, e.g. Albe. Permission-based reasons are request-scoped (they depend on who is asking) and can\nonly be determined where the acting user is known, e.g. the dashboard. When both apply, the\nkey-state reason wins.',
  })
  .openapi('RotateUnavailableReason')

const ActionUnavailableRotateUnavailableReasonSchema = z
  .object({
    status: z
      .literal('unavailable')
      .default('unavailable')
      .exactOptional()
      .openapi({ title: 'Status' }),
    reason: z.union([RotateUnavailableReasonSchema, z.null().nullable()]).exactOptional(),
  })
  .openapi({ title: 'ActionUnavailable[RotateUnavailableReason]', required: [] })
  .openapi('ActionUnavailableRotateUnavailableReason')

const DeleteUnavailableReasonSchema = z
  .literal('not_allowed')
  .openapi({
    title: 'DeleteUnavailableReason',
    description:
      'Machine-readable reason why an API key cannot be deleted.\n\nDeletion eligibility currently turns on a single request-scoped permission: whether the acting\nuser may delete (archive) the key. The reason is therefore determined where the acting user is\nknown (e.g. the dashboard), not from the key\'s scope or state. Consumers should treat unknown\nvalues as "delete unavailable".',
  })
  .openapi('DeleteUnavailableReason')

const ActionUnavailableDeleteUnavailableReasonSchema = z
  .object({
    status: z
      .literal('unavailable')
      .default('unavailable')
      .exactOptional()
      .openapi({ title: 'Status' }),
    reason: z.union([DeleteUnavailableReasonSchema, z.null().nullable()]).exactOptional(),
  })
  .openapi({ title: 'ActionUnavailable[DeleteUnavailableReason]', required: [] })
  .openapi('ActionUnavailableDeleteUnavailableReason')

const APIKeyActionsSchema = z
  .object({
    rotate: z
      .union([
        z
          .xor([ActionAvailableSchema, ActionUnavailableRotateUnavailableReasonSchema])
          .openapi({
            discriminator: {
              propertyName: 'status',
              mapping: {
                available: '#/components/schemas/ActionAvailable',
                unavailable: '#/components/schemas/ActionUnavailable_RotateUnavailableReason_',
              },
            },
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({ title: 'Rotate' }),
    delete: z
      .union([
        z
          .xor([ActionAvailableSchema, ActionUnavailableDeleteUnavailableReasonSchema])
          .openapi({
            discriminator: {
              propertyName: 'status',
              mapping: {
                available: '#/components/schemas/ActionAvailable',
                unavailable: '#/components/schemas/ActionUnavailable_DeleteUnavailableReason_',
              },
            },
          }),
        z.null().nullable(),
      ])
      .exactOptional()
      .openapi({ title: 'Delete' }),
  })
  .openapi({
    title: 'APIKeyActions',
    description:
      'Per-action availability for an API key, keyed by action name.\n\nThis is the generic, reusable shape for surfacing what a viewer may do with a resource on\nget/list endpoints: each action maps to a value that is either available or unavailable with an\noptional reason code. Add fields here as more actions are exposed.\n\nEvery action is opt-in: fields default to ``None`` (the action is absent), and an absent action\nmeans "unavailable, with no specified reason". An action is only available when a producer\nexplicitly sets it to ``ActionAvailable``. This keeps permissions opt-in rather than opt-out, so\nforgetting to populate an action can never accidentally expose it.',
    required: [],
  })
  .openapi('APIKeyActions')

