const BudgetDetailSchema = z
  .object({
    usage_percentage: z
      .number()
      .openapi({
        examples: [42.5],
        title: 'Usage Percentage',
        description: 'Percentage of the budget consumed for the requested billing period (0-100).',
      }),
    initial_budget: z
      .number()
      .openapi({
        examples: [300],
        title: 'Initial Budget',
        description:
          'Initial budget allocated for the billing period, expressed in the budget currency.',
      }),
    currency: z
      .union([z.string(), z.null().nullable()])
      .exactOptional()
      .openapi({
        examples: ['EUR'],
        title: 'Currency',
        description:
          'ISO 4217 currency code of the budget (e.g. EUR, USD). The applicable budget is lazily materialized for the requested period, so this is only null when no budget could be derived.',
      }),
    reset_at: z.iso
      .datetime({ offset: true })
      .openapi({
        examples: ['2026-08-01T00:00:00Z'],
        title: 'Reset At',
        description:
          'Timestamp at which the requested billing period resets (start of the next period).',
      }),
    payg_enabled: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        examples: [false],
        title: 'Payg Enabled',
        description:
          'Whether pay-as-you-go overage is enabled for this budget type. Only meaningful for the Vibe budget.',
      }),
  })
  .openapi({ title: 'BudgetDetail', required: ['usage_percentage', 'initial_budget', 'reset_at'] })
  .openapi('BudgetDetail')

