export const getV1ConnectorsRoute = createRoute({
  method: 'get',
  path: '/v1/connectors',
  tags: ['beta.connectors'],
  summary: 'List all connectors.',
  description: 'List all your custom connectors with keyset pagination and filters.',
  operationId: 'connector_list_v1',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([['supports_mcp', ['query_filters']]])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          query_filters: z
            .object({
              supports_mcp: z
                .preprocess(
                  (val) => (val === 'null' ? null : val),
                  z.preprocess(
                    ((read) => (val: unknown) => {
                      const result = read.safeParse(val)
                      return result.success ? result.data : val
                    })(z.stringbool()),
                    z.union([z.boolean(), z.null().nullable()]),
                  ),
                )
                .exactOptional()
                .openapi({
                  title: 'Supports Mcp',
                  description:
                    'Filter connectors by whether they expose an MCP-compatible tool interface.',
                }),
            })
            .default({})
            .exactOptional()
            .openapi({
              param: {
                name: 'query_filters',
                in: 'query',
                required: false,
                schema: {
                  type: 'object',
                  properties: {
                    supports_mcp: {
                      anyOf: [{ type: 'boolean' }, { type: 'null' }],
                      title: 'Supports Mcp',
                      description:
                        'Filter connectors by whether they expose an MCP-compatible tool interface.',
                    },
                  },
                  title: 'ConnectorsQueryFilters',
                  default: { fetch_user_data: false, check_credentials_status: false },
                },
              },
              title: 'ConnectorsQueryFilters',
              required: [],
            }),
          cursor: ((schema) =>
            z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
            z.union([
              z.string(),
              z.preprocess((val) => (val === 'null' ? null : val), z.null().nullable()),
            ]),
          )
            .exactOptional()
            .openapi({
              param: {
                name: 'cursor',
                in: 'query',
                required: false,
                schema: { anyOf: [{ type: 'string' }, { type: 'null' }], title: 'Cursor' },
              },
              title: 'Cursor',
            }),
          page_size: z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int().min(1).max(1000),
            )
            .default(100)
            .exactOptional()
            .openapi({
              param: {
                name: 'page_size',
                in: 'query',
                required: false,
                schema: {
                  type: 'integer',
                  title: 'Page Size',
                  maximum: 1000,
                  minimum: 1,
                  default: 100,
                },
              },
              title: 'Page Size',
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful Response',
      content: { 'application/json': { schema: PaginatedConnectorsSchema } },
    },
    422: {
      description: 'Validation Error',
      content: { 'application/json': { schema: HTTPValidationErrorSchema } },
    },
  },
})

